/**
 * Informe HTML imprimible (PDF vía navegador).
 * Branding + metadatos + huella de contenido (integridad documental).
 */

export type ReportMeta = {
  /** Título del informe */
  title: string;
  /** Subtítulo / periodo / estado */
  subtitle?: string;
  /** Nombre del negocio (tenant) */
  businessName?: string;
  /** Usuario que genera el informe */
  generatedBy?: string;
  /** Rol del usuario */
  generatedByRole?: string;
  /** Producto / sistema */
  systemName?: string;
  /** Logo (data URI o URL absoluta). Por defecto icono ÁbacoPhy embebido. */
  logoUrl?: string;
  /** Texto libre adicional en pie */
  note?: string;
};


/** Logo oficial embebido (public/abacus_color_icon.svg) — funciona en ventanas blob. */
export const ABACOPHY_LOGO_DATA_URI =
  'data:image/svg+xml;base64,';

export function escapeHtml(s: string): string {
  return String(s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

export function tableHtml(
  headers: string[],
  rows: Array<Array<string | number>>,
  numericCols: number[] = [],
): string {
  const num = new Set(numericCols);
  const thead = headers
    .map((h, i) => `<th class="${num.has(i) ? 'num' : ''}">${escapeHtml(h)}</th>`)
    .join('');
  const tbody = rows
    .map(
      (r) =>
        `<tr>${r
          .map((c, i) => `<td class="${num.has(i) ? 'num' : ''}">${escapeHtml(String(c))}</td>`)
          .join('')}</tr>`,
    )
    .join('');
  return `<table><thead><tr>${thead}</tr></thead><tbody>${tbody}</tbody></table>`;
}

/**
 * Huella estable del payload (no es firma criptográfica de clave privada;
 * sí permite verificar que el documento no se alteró tras generarse).
 * Formato: AP- + 16 hex (SHA-256 truncado o fallback FNV).
 */
export async function contentFingerprint(payload: string): Promise<string> {
  const data = new TextEncoder().encode(payload);
  if (typeof crypto !== 'undefined' && crypto.subtle) {
    try {
      const buf = await crypto.subtle.digest('SHA-256', data);
      const hex = [...new Uint8Array(buf)].map((b) => b.toString(16).padStart(2, '0')).join('');
      return `AP-${hex.slice(0, 16).toUpperCase()}`;
    } catch {
      /* fallback */
    }
  }
  // FNV-1a 32-bit × 2 passes for display
  let h = 2166136261;
  for (let i = 0; i < data.length; i++) {
    h ^= data[i];
    h = Math.imul(h, 16777619);
  }
  const a = (h >>> 0).toString(16).padStart(8, '0');
  let h2 = 2166136261;
  for (let i = data.length - 1; i >= 0; i--) {
    h2 ^= data[i];
    h2 = Math.imul(h2, 16777619);
  }
  const b = (h2 >>> 0).toString(16).padStart(8, '0');
  return `AP-${(a + b).toUpperCase()}`;
}

function sanitizeFilename(s: string): string {
  return String(s)
    .trim()
    .replace(/[^\w\-]+/g, '_')
    .replace(/_+/g, '_')
    .slice(0, 60);
}

/**
 * Abre informe profesional: cabecera de marca, metadatos, cuerpo, pie con huella.
 */
export async function openPrintWindow(
  meta: ReportMeta | string,
  bodyHtml: string,
  /** Texto canónico para la huella (filas del informe). Si se omite, se usa bodyHtml. */
  fingerprintSource?: string,
): Promise<void> {
  const m: ReportMeta = typeof meta === 'string' ? { title: meta } : meta;
  const system = m.systemName || 'ÁbacoPhy';
  const business = m.businessName || 'Negocio';
  const logoSrc =
    m.logoUrl ||
    (typeof window !== 'undefined' && window.location?.origin
      ? `${window.location.origin}/abacus_color_icon.svg`
      : ABACOPHY_LOGO_DATA_URI);
  // Prefer embedded data URI for blob windows (no network dependency)
  const logoEmbed = m.logoUrl || ABACOPHY_LOGO_DATA_URI;
  const when = new Date();
  const whenIso = when.toISOString();
  const whenLocal = when.toLocaleString('es', {
    dateStyle: 'full',
    timeStyle: 'medium',
  });

  const fpInput = [
    m.title,
    m.subtitle || '',
    business,
    m.generatedBy || '',
    whenIso.slice(0, 16),
    fingerprintSource ?? bodyHtml,
  ].join('|');
  const fingerprint = await contentFingerprint(fpInput);
  const docId = `DOC-${when.getTime().toString(36).toUpperCase()}-${fingerprint.slice(3, 7)}`;

  const html = `<!DOCTYPE html>
<html lang="es">
<head>
  <meta charset="utf-8" />
  <title>${escapeHtml(m.title)} · ${escapeHtml(business)}</title>
  <meta name="generator" content="${escapeHtml(system)}" />
  <meta name="document-id" content="${escapeHtml(docId)}" />
  <meta name="content-fingerprint" content="${escapeHtml(fingerprint)}" />
  <style>
    :root { color-scheme: light; }
    * { box-sizing: border-box; }
    body {
      font-family: "Segoe UI", system-ui, -apple-system, Roboto, sans-serif;
      margin: 0;
      color: #0f172a;
      font-size: 12.5px;
      background: #fff;
      line-height: 1.45;
    }
    .page {
      max-width: 920px;
      margin: 0 auto;
      padding: 28px 32px 40px;
    }
    .brand {
      display: flex;
      justify-content: space-between;
      align-items: flex-start;
      gap: 16px;
      padding-bottom: 14px;
      border-bottom: 2px solid #0f172a;
      margin-bottom: 18px;
    }
    .brand-left {
      display: flex;
      gap: 12px;
      align-items: center;
    }
    .logo {
      width: 44px;
      height: 44px;
      border-radius: 10px;
      object-fit: contain;
      flex-shrink: 0;
      background: #fff;
    }
    .brand-name {
      font-size: 1.05rem;
      font-weight: 800;
      letter-spacing: -0.02em;
      margin: 0;
    }
    .brand-sub {
      margin: 2px 0 0;
      color: #64748b;
      font-size: 0.8rem;
    }
    .brand-right {
      text-align: right;
      font-size: 0.72rem;
      color: #64748b;
    }
    .brand-right strong {
      display: block;
      color: #0f172a;
      font-size: 0.85rem;
      margin-bottom: 2px;
    }
    h1 {
      font-size: 1.35rem;
      margin: 0 0 4px;
      font-weight: 800;
      letter-spacing: -0.02em;
    }
    .sub {
      color: #475569;
      margin: 0 0 14px;
      font-size: 0.88rem;
    }
    .meta-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 8px 20px;
      padding: 12px 14px;
      background: #f8fafc;
      border: 1px solid #e2e8f0;
      border-radius: 10px;
      margin-bottom: 18px;
      font-size: 0.8rem;
    }
    .meta-grid dt {
      margin: 0;
      color: #64748b;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.04em;
      font-size: 0.65rem;
    }
    .meta-grid dd {
      margin: 2px 0 0;
      font-weight: 600;
      color: #0f172a;
      word-break: break-all;
    }
    table { width: 100%; border-collapse: collapse; margin-top: 4px; }
    th, td {
      border: 1px solid #cbd5e1;
      padding: 7px 9px;
      text-align: left;
    }
    th {
      background: #f1f5f9;
      font-size: 0.7rem;
      text-transform: uppercase;
      letter-spacing: 0.04em;
      color: #334155;
    }
    td.num, th.num { text-align: right; font-variant-numeric: tabular-nums; }
    tbody tr:nth-child(even) { background: #fafbfc; }
    .foot {
      margin-top: 28px;
      padding-top: 14px;
      border-top: 1px solid #e2e8f0;
      display: grid;
      gap: 8px;
      font-size: 0.72rem;
      color: #64748b;
    }
    .foot-row {
      display: flex;
      justify-content: space-between;
      gap: 12px;
      flex-wrap: wrap;
    }
    .fp {
      font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
      font-size: 0.7rem;
      color: #0f172a;
      background: #f1f5f9;
      padding: 2px 6px;
      border-radius: 4px;
    }
    .seal {
      margin-top: 6px;
      padding: 10px 12px;
      border: 1px dashed #94a3b8;
      border-radius: 8px;
      background: #f8fafc;
      font-size: 0.7rem;
      color: #475569;
    }
    .seal strong { color: #0f172a; }
    .toolbar { margin-bottom: 16px; }
    .toolbar button {
      padding: 8px 14px; border-radius: 8px; border: 1px solid #0f172a;
      background: #0f172a; color: #fff; cursor: pointer; font-weight: 600;
    }
    @media print {
      .toolbar { display: none !important; }
      .page { padding: 0; max-width: none; }
      body { margin: 0; }
    }
  </style>
</head>
<body>
  <div class="page">
    <div class="toolbar">
      <button type="button" onclick="window.print()">Imprimir / Guardar PDF</button>
    </div>

    <header class="brand">
      <div class="brand-left">
        <img class="logo" src="${logoEmbed}" alt="ÁbacoPhy" width="44" height="44" />
        <div>
          <p class="brand-name">${escapeHtml(system)}</p>
          <p class="brand-sub">Contabilidad · inventario · POS</p>
        </div>
      </div>
      <div class="brand-right">
        <strong>${escapeHtml(business)}</strong>
        Informe oficial de negocio<br />
        ${escapeHtml(whenLocal)}
      </div>
    </header>

    <h1>${escapeHtml(m.title)}</h1>
    ${m.subtitle ? `<p class="sub">${escapeHtml(m.subtitle)}</p>` : ''}

    <dl class="meta-grid">
      <div>
        <dt>Generado por</dt>
        <dd>${escapeHtml(m.generatedBy || '—')}${m.generatedByRole ? ` · ${escapeHtml(m.generatedByRole)}` : ''}</dd>
      </div>
      <div>
        <dt>Fecha de emisión</dt>
        <dd>${escapeHtml(whenLocal)}</dd>
      </div>
      <div>
        <dt>ID de documento</dt>
        <dd><span class="fp">${escapeHtml(docId)}</span></dd>
      </div>
      <div>
        <dt>Huella de contenido</dt>
        <dd><span class="fp">${escapeHtml(fingerprint)}</span></dd>
      </div>
    </dl>

    ${bodyHtml}

    <footer class="foot">
      <div class="foot-row">
        <span>Documento generado por <strong>${escapeHtml(system)}</strong> · ${escapeHtml(business)}</span>
        <span>${escapeHtml(whenIso)}</span>
      </div>
      <div class="seal">
        <strong>Integridad documental.</strong>
        La huella <span class="fp">${escapeHtml(fingerprint)}</span> se calcula sobre el contenido del informe
        (SHA-256 truncado). Cualquier alteración posterior del listado producirá una huella distinta.
        No sustituye una firma electrónica cualificada; acredita origen y momento de generación en ${escapeHtml(system)}.
        ${m.note ? `<br /><br />${escapeHtml(m.note)}` : ''}
      </div>
    </footer>
  </div>
</body>
</html>`;

  const blob = new Blob([html], { type: 'text/html;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const w = window.open(url, '_blank', 'noopener,noreferrer,width=960,height=720');
  if (!w) {
    const a = document.createElement('a');
    a.href = url;
    a.download = `${sanitizeFilename(m.title) || 'informe'}-${Date.now()}.html`;
    a.rel = 'noopener';
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 60_000);
    throw new Error(
      'Ventana bloqueada. Se descargó el HTML: ábralo e imprima como PDF.',
    );
  }
  setTimeout(() => URL.revokeObjectURL(url), 60_000);
}
